.sl-course-explorer.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-course-explorer .sl-text-primary { color: var(--smartlearn-primary); }
.sl-course-explorer .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-course-explorer .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-course-explorer .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-course-explorer .sl-border { border-color: var(--smartlearn-card-border); }
.sl-course-explorer .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-course-explorer h2, .sl-course-explorer h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-course-explorer .sl-tracking-wide { letter-spacing: 0.1em; }
.sl-course-explorer .sl-media-fallback { background-color: var(--smartlearn-card-bg); }
.sl-course-explorer .sl-filter-btn {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
    border: 1px solid var(--smartlearn-card-border);
    transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}
.sl-course-explorer .sl-filter-btn:hover,
.sl-course-explorer .sl-filter-btn:focus-visible {
    color: var(--smartlearn-text);
    border-color: var(--smartlearn-primary);
}
.sl-course-explorer .sl-filter-btn.is-active {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border-color: var(--smartlearn-btn-bg);
}
.sl-course-explorer .sl-filter-item {
    transition: opacity 0.25s ease, transform 0.25s ease;
}
.sl-course-explorer .sl-filter-item.is-hiding {
    opacity: 0;
    transform: scale(0.96);
}
.sl-course-explorer .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-course-explorer .sl-hover-zoom { transition: transform 0.6s ease; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-course-explorer .sl-hover-card { transition: transform 0.3s ease, box-shadow 0.3s ease; }
    .sl-course-explorer .sl-hover-card:hover { transform: translateY(-5px); box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.1); }
    .sl-course-explorer .sl-hover-card:hover .sl-hover-zoom { transform: scale(1.05); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-course-explorer .sl-hover-zoom, .sl-course-explorer .sl-hover-card, .sl-course-explorer .sl-filter-item, .sl-course-explorer .sl-filter-btn { transition: none; }
}
@media (min-width: 992px) {
    .sl-course-explorer { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}

