(function() {
    const init = () => {
        document.querySelectorAll('.sl-course-explorer').forEach((section) => {
            if (section.dataset.slInit === '1') return;
            section.dataset.slInit = '1';

            const filterBtns = Array.from(section.querySelectorAll('.sl-filter-btn'));
            const items = Array.from(section.querySelectorAll('.sl-filter-item'));
            const statusEl = section.querySelector('.sl-filter-status');
            const emptyEl = section.querySelector('.sl-filter-empty');
            if (!filterBtns.length || !items.length) return;

            const timers = new WeakMap();
            const isReduced = () => window.matchMedia('(prefers-reduced-motion: reduce)').matches;

            filterBtns.forEach((btn) => {
                btn.addEventListener('click', () => {
                    const filter = (btn.getAttribute('data-filter') || 'all').trim().toLowerCase();

                    filterBtns.forEach((b) => {
                        const active = b === btn;
                        b.classList.toggle('is-active', active);
                        b.setAttribute('aria-pressed', active ? 'true' : 'false');
                    });

                    let visibleCount = 0;
                    const delay = isReduced() ? 0 : 220;

                    items.forEach((item) => {
                        if (timers.has(item)) {
                            clearTimeout(timers.get(item));
                            timers.delete(item);
                        }
                        const cats = (item.getAttribute('data-category') || '').trim().toLowerCase().split(/\s+/);
                        const match = filter === 'all' || cats.includes(filter);

                        if (match) {
                            visibleCount++;
                            item.classList.remove('d-none');
                            requestAnimationFrame(() => {
                                item.classList.remove('is-hiding');
                            });
                        } else if (delay === 0) {
                            item.classList.add('is-hiding', 'd-none');
                        } else {
                            item.classList.add('is-hiding');
                            const tid = setTimeout(() => {
                                item.classList.add('d-none');
                                timers.delete(item);
                            }, delay);
                            timers.set(item, tid);
                        }
                    });

                    if (statusEl) {
                        statusEl.textContent = `Showing ${visibleCount} ${visibleCount === 1 ? 'course' : 'courses'}`;
                    }
                    if (emptyEl) {
                        emptyEl.classList.toggle('d-none', visibleCount > 0);
                    }
                });
            });
        });
    };
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
